//! The C ABI shared by the loader (`winmm.dll`) and mods.
//!
//! Mods are ordinary `cdylib`s. The loader calls the exported
//! [`ENTRY_SYMBOL`] with a pointer to [`HostApi`]; the mod returns a
//! [`ModDescriptor`] describing itself and its callbacks. Everything crossing
//! the boundary is `#[repr(C)]`, so mods and the loader do not need to be built
//! by the same compiler version.

use core::ffi::c_void;

/// Bumped on any breaking change to the structs in this module.
pub const ABI_VERSION: u32 = 4;

/// Symbol every mod DLL exports (generated by [`crate::hd_mod!`]).
pub const ENTRY_SYMBOL: &[u8] = b"hdmod_entry\0";

/// Signature of [`ENTRY_SYMBOL`].
pub type EntryFn = unsafe extern "C" fn(host: *const HostApi) -> *const ModDescriptor;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct StrRef {
    pub ptr: *const u8,
    pub len: usize,
}

impl StrRef {
    pub const fn new(s: &'static str) -> Self {
        Self { ptr: s.as_ptr(), len: s.len() }
    }

    pub fn of(s: &str) -> Self {
        Self { ptr: s.as_ptr(), len: s.len() }
    }

    /// # Safety
    /// `ptr`/`len` must describe valid UTF-8 that outlives the returned slice.
    pub unsafe fn as_str<'a>(&self) -> &'a str {
        if self.ptr.is_null() {
            return "";
        }
        core::str::from_utf8_unchecked(core::slice::from_raw_parts(self.ptr, self.len))
    }
}

#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum LogLevel {
    Error = 0,
    Warn = 1,
    Info = 2,
    Debug = 3,
}

/// Addresses inside `hyperdemon.exe` resolved by the loader at startup via byte
/// signatures (see `docs/REVERSE_ENGINEERING.md`). A field is `0` when its
/// signature did not match, e.g. after a game update.
#[repr(C)]
#[derive(Clone, Copy, Default, Debug)]
pub struct GameAddrs {
    /// `Game**`: root game/session object (`DAT_1403d91f0` in build 7612dd72).
    pub game_ptr: usize,
    /// `App**`: engine application object (`DAT_1403d91d8`).
    pub app_ptr: usize,
    /// `ImGuiContext**`: Dear ImGui's `GImGui` (`DAT_1403d99e0`).
    pub imgui_ctx_ptr: usize,
    /// `bool ImGui::Begin(const char*, bool*, ImGuiWindowFlags)`
    pub imgui_begin: usize,
    /// `void ImGui::End()`
    pub imgui_end: usize,
    /// `void ImGui::TextV(const char* fmt, va_list)`
    pub imgui_textv: usize,
    /// `void ImGui::SameLine(float offset_from_start_x, float spacing)`
    pub imgui_same_line: usize,
    /// `std::string& std::string::assign(std::string*, const char*, size_t)`
    /// (the game's own, so allocations use the game's heap).
    pub string_assign: usize,
    /// `void vector<ClipEntry>::resize(vector*, size_t, vector*)`; new
    /// entries get `valid = -1` ("not loaded").
    pub clip_list_resize: usize,
    /// `void World::SpawnNearPlayer(World*, int type, const float offset[3])`
    pub world_spawn_near_player: usize,
    /// `ImFont::RenderText(font, ImDrawList*, size, ImVec2 pos, u32 col,
    /// const ImVec4& clip, begin, end, wrap_width, cpu_fine_clip)`
    pub font_render_text: usize,
    /// `ImVec2 ImFont::CalcTextSizeA(font, size, max_width, wrap_width, begin,
    /// end, remaining)` (returned through a hidden pointer)
    pub font_calc_text_size: usize,
    /// `void ImGui::PushFont(ImFont*)` / `void ImGui::PopFont()`
    pub imgui_push_font: usize,
    pub imgui_pop_font: usize,
}

/// Callbacks a mod may provide. Every field is optional.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct ModCallbacks {
    /// Main thread, once per fixed simulation step, after the game's tick.
    pub on_tick: Option<unsafe extern "C" fn(dt: f32)>,
    /// Main thread, once per frame, inside the game's HUD ImGui frame (between
    /// `NewFrame` and `Render`), so ImGui calls are valid here.
    pub on_ui: Option<unsafe extern "C" fn()>,
    /// Render thread, right before `SwapBuffers`, with the GL context current.
    pub on_frame: Option<unsafe extern "C" fn()>,
    /// Called once before the process exits.
    pub on_unload: Option<unsafe extern "C" fn()>,
    /// Main thread, right before an HTTP request is handed to the network
    /// worker. `request` is the game's request object; mods may rewrite its
    /// URL (see `hd_sdk::net`).
    pub on_http_request: Option<unsafe extern "C" fn(request: *mut c_void)>,
    /// Main thread, after the gameplay World ticked (only while a run is
    /// active). `world` is the World object.
    pub on_world_tick: Option<unsafe extern "C" fn(world: *mut c_void, dt: f32)>,
    /// Main thread, right before the gameplay World ticks.
    pub on_world_tick_pre: Option<unsafe extern "C" fn(world: *mut c_void, dt: f32)>,
    /// Main thread, inside the UI pass: right before / after the game draws
    /// the training panel and runs the training steps (`FUN_140090150`;
    /// every frame on the menu/run scene, training or not).
    pub on_training_hud_begin: Option<unsafe extern "C" fn()>,
    pub on_training_hud_end: Option<unsafe extern "C" fn()>,
}

#[repr(C)]
pub struct ModDescriptor {
    pub abi_version: u32,
    pub name: StrRef,
    pub version: StrRef,
    pub author: StrRef,
    pub description: StrRef,
    pub callbacks: ModCallbacks,
}

// Safety: descriptors are immutable statics.
unsafe impl Sync for ModDescriptor {}

/// Services the loader provides to mods. Pointer stays valid for the life of
/// the process.
#[repr(C)]
pub struct HostApi {
    pub abi_version: u32,
    /// `size_of::<HostApi>()` as built by the loader, for forward compat.
    pub size: u32,
    /// Base address of `hyperdemon.exe` in memory.
    pub game_base: usize,
    /// Size of the mapped `hyperdemon.exe` image.
    pub game_size: usize,
    pub addrs: GameAddrs,
    /// Absolute path of the `mods` directory (UTF-8).
    pub mods_dir: StrRef,

    pub log: unsafe extern "C" fn(level: LogLevel, module: StrRef, msg: StrRef),

    /// Create and enable an inline hook through the loader's shared MinHook
    /// instance. On success writes the trampoline to `*original` and returns 0.
    pub hook_create: unsafe extern "C" fn(
        target: *mut c_void,
        detour: *mut c_void,
        original: *mut *mut c_void,
    ) -> i32,
    /// Disable and remove a hook previously created with `hook_create`.
    pub hook_remove: unsafe extern "C" fn(target: *mut c_void) -> i32,

    /// Find an IDA-style pattern (`"48 8B ?? 05"`) in the game's `.text`.
    /// Returns 0 when not found.
    pub find_pattern: unsafe extern "C" fn(pattern: StrRef) -> usize,
}

// Safety: the host table is immutable after the loader publishes it, and the
// raw pointers it holds (`mods_dir`) point to leaked, never-mutated data.
unsafe impl Sync for HostApi {}
unsafe impl Send for HostApi {}
